(() => {
  const results = [];
  document.querySelectorAll('button, a').forEach(el => {
    const label = (el.getAttribute('aria-label') || '') + '|' + (el.getAttribute('data-testid') || '') + '|' + el.textContent.trim().slice(0, 40);
    if (/save|Save/i.test(label)) {
      results.push({tag: el.tagName, label: label.slice(0, 120), visible: !!(el.offsetParent || el.getClientRects().length)});
    }
  });
  return results;
})()

(() => {
  const titles = Array.from(document.querySelectorAll('[data-testid*="Panel header title"]')).map(el => el.textContent.trim());
  const noData = Array.from(document.querySelectorAll('[class*="no-data"], [data-testid*="no-data"]')).map(el => el.textContent.trim()).filter(t => t);
  return {panelTitles: titles, noDataMessages: noData};
})()

(() => {
  const panel = document.querySelector('[data-testid*="panel content"], .panel-content, [class*="panel-container"]');
  const loading = document.querySelectorAll('[class*="loading"], [data-testid*="loading"]').length;
  const viz = document.querySelectorAll('svg path, canvas').length;
  return {
    panelText: panel ? panel.textContent.trim().slice(0, 200) : null,
    loadingElements: loading,
    vizElements: viz,
    bodyHasNoData: document.body.textContent.includes('No data')
  };
})()

(() => {
  const dialogs = document.querySelectorAll('[role="dialog"]');
  return {
    dialogCount: dialogs.length,
    hasRenameInput: !!document.querySelector('input[name="title"], input[aria-label*="title" i]'),
    titleInput: (() => {
      const inputs = document.querySelectorAll('input');
      return Array.from(inputs).map(i => ({name: i.name, ariaLabel: i.getAttribute('aria-label'), value: i.value, visible: !!(i.offsetParent || i.getClientRects().length)})).filter(i => i.visible && (i.name === 'title' || /title/i.test(i.ariaLabel || '')));
    })()
  };
})()

(() => {
  // Find all elements related to tags
  const all = document.body.innerText;
  const tagsSection = all.substring(all.indexOf('Tags'), all.indexOf('Tags') + 200);
  return tagsSection;
})()

(() => {
  // Look for tags anywhere on the dashboard page
  const tags = Array.from(document.querySelectorAll('[class*="tag"], [data-testid*="tag"], [aria-label*="tag"]')).map(el => ({
    text: el.textContent.trim(),
    ariaLabel: el.getAttribute('aria-label'),
    class: el.className
  }));
  // Also search for any element containing "bench" that looks like a tag
  const allSpans = Array.from(document.querySelectorAll('span, div, button')).filter(el => {
    const t = el.textContent.trim();
    return t === 'bench' && el.children.length === 0 && t.length < 20;
  }).map(el => ({tag: el.tagName, text: el.textContent.trim(), ariaLabel: el.getAttribute('aria-label')}));
  return {classBased: tags, textBased: allSpans};
})()

(() => {
  // Look for any visible menu, popover, or dropdown
  const menus = Array.from(document.querySelectorAll('[role="menu"], [role="dialog"], .menu, [class*="popover"], [class*="dropdown"]'));
  return menus.map(m => ({
    role: m.getAttribute('role'),
    class: m.className.substring(0, 80),
    visible: !!(m.offsetParent || m.getClientRects().length),
    items: Array.from(m.querySelectorAll('button, a, [role="menuitem"]')).map(i => ({text: i.textContent.trim().slice(0, 30)}))
  }));
})()

(() => {
  // Find the panel header toolbar - look for a button with Edit or similar
  const ph = document.querySelector('[aria-label*="fwgr20-n3 Availability"]');
  if (!ph) return 'section not found';
  // Look for any button inside
  const btns = ph.querySelectorAll('button, a');
  return Array.from(btns).map(b => ({
    tag: b.tagName,
    text: b.textContent.trim().slice(0, 30),
    ariaLabel: b.getAttribute('aria-label'),
    visible: !!(b.offsetParent || b.getClientRects().length)
  }));
})()

(() => {
  const ph = document.querySelector('[aria-label*="fwgr20-n3 Availability"]');
  if (!ph) return 'not found';
  // Return outer HTML of the whole section
  return ph.outerHTML.substring(0, 2000);
})()
